/* prog23_longest_common_prefix.c
 * Re‑implementation of the original binary's observable behaviour.
 *
 * Behaviour:
 *   - If more than 64 arguments are supplied (excluding the program name)
 *       prints "TOO_MANY" and exits.
 *   - If any argument length exceeds 1024 characters
 *       prints "TOO_LONG" and exits.
 *   - If no arguments are supplied (argc == 1)
 *       prints "EMPTY" and exits.
 *   - Otherwise prints the longest common prefix of all arguments,
 *       followed by a newline.
 *
 * The program returns 0 in all cases.
 */

#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    int n = argc - 1;                 /* number of real arguments */

    /* 1. Too many arguments */
    if (n > 64) {
        puts("TOO_MANY");
        return 0;
    }

    /* 2. No arguments */
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    /* 3. Length check (max 1024) */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* 4. Compute longest common prefix */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);

    for (int i = 2; i < argc && prefix_len > 0; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j;               /* shrink to the common part */
    }

    /* 5. Output the prefix and a newline */
    fwrite(first, 1, prefix_len, stdout);
    putchar('\n');

    return 0;
}
